Here are the core battle system objects in C# terms, designed to integrate magic, cybernetics, and turn-based mechanics while staying consistent with your world:

```csharp
public interface ICombatant {
    string Name { get; }
    int CurrentHP { get; set; }
    int MaxHP { get; }
    int CurrentMana { get; set; }
    int MaxMana { get; }
    bool IsPlayer { get; }
    void TakeDamage(int damage);
    void RestoreMana(int amount);
    void ExecuteTurn();
}

public class Player : ICombatant {
    public string Name { get; } = "Main Character";
    public int CurrentHP { get; set; } = 100;
    public int MaxHP => 100 + (int)(CyberneticEnhancement * 0.5f);
    public int CurrentMana { get; set; } = 80;
    public int MaxMana => 80 + (int)(MagicStrength * 0.75f);
    public bool IsPlayer => true;
    public int MagicStrength { get; set; } = 15;
    public float CyberneticEnhancement { get; set; } = 10.0f;
    public List<Equipment> EquippedItems { get; } = new();
    public List<Skill> ActiveSkills { get; } = new();

    public void ExecuteTurn() {
        // Logic for player turn (e.g., select skill/item)
    }
}

public class Enemy : ICombatant {
    public string Name { get; }
    public int CurrentHP { get; set; }
    public int MaxHP { get; }
    public int CurrentMana { get; set; }
    public int MaxMana { get; }
    public bool IsPlayer => false;
    public EnemyType Type { get; }

    public Enemy(string name, int hp, int mana, EnemyType type) {
        Name = name;
        CurrentHP = MaxHP = hp;
        CurrentMana = MaxMana = mana;
        Type = type;
    }

    public void ExecuteTurn() {
        // AI logic based on EnemyType (e.g., "Cyber-Ork" might use melee + hacking)
    }
}

public class Skill {
    public string Name { get; }
    public int ManaCost { get; }
    public int BaseDamage { get; }
    public bool IsMagic { get; }
    public float Cooldown { get; set; }

    public Skill(string name, int manaCost, int damage, bool isMagic) {
        Name = name;
        ManaCost = manaCost;
        BaseDamage = damage;
        IsMagic = isMagic;
    }

    public int CalculateEffectiveDamage(ICombatant user) {
        return BaseDamage + (IsMagic ? user.MagicStrength : 0);
    }
}

public class Equipment {
    public string Name { get; }
    public bool IsWeapon { get; }
    public float AttackModifier { get; }
    public float CyberneticBonus { get; }
    public float MagicBonus { get; }

    public Equipment(string name, bool isWeapon, float attackMod, float cyberBonus, float magicBonus) {
        Name = name;
        IsWeapon = isWeapon;
        AttackModifier = attackMod;
        CyberneticBonus = cyberBonus;
        MagicBonus = magicBonus;
    }
}

public enum EnemyType {
    CyberOrk,
    MageLich,
    TechnoWraith,
    StreetGang
}
```

Key integrations with your world:  
- **Magic + Cybernetics**: `MagicStrength` and `CyberneticEnhancement` directly impact damage/HP (e.g., a cybernetic arm might boost melee damage but drain mana)  
- **Cleveland setting**: `EnemyType` includes "StreetGang" for urban threats  
- **Economy ties**: `Equipment` includes cybernetic/magic bonuses for items like "Mana Battery" (consumable) or "Leyline-Powered Gun" (weapon)  
- **Turn system**: `ExecuteTurn()` methods handle player/enemy action sequencing  

This structure supports:  
- Party members with hybrid magic/cyber abilities  
- Items that blend fantasy and tech (e.g., "Potion of Cyber-Regeneration")  
- Enemy types reflecting your alternate-history Cleveland  

